SELECT ${@com.group.antian.framework.mybatis.core.util.SqlDialectUtils@month('order_date')} AS month,
       COALESCE(SUM(total_price), 0) AS current_price
  FROM crm_contract
 WHERE deleted = 0
   AND audit_status = ${@com.group.antian.module.crm.enums.common.CrmAuditStatusEnum@APPROVE.status}
   AND owner_user_id IN

            #{userId}

   AND ${@com.group.antian.framework.mybatis.core.util.SqlDialectUtils@year('order_date')} = #{year}
 GROUP BY ${@com.group.antian.framework.mybatis.core.util.SqlDialectUtils@month('order_date')}

SELECT ${@com.group.antian.framework.mybatis.core.util.SqlDialectUtils@month('return_time')} AS month,
       COALESCE(SUM(price), 0) AS current_price
  FROM crm_receivable
 WHERE deleted = 0
   AND audit_status = ${@com.group.antian.module.crm.enums.common.CrmAuditStatusEnum@APPROVE.status}
   AND owner_user_id IN

            #{userId}

   AND ${@com.group.antian.framework.mybatis.core.util.SqlDialectUtils@year('return_time')} = #{year}
 GROUP BY ${@com.group.antian.framework.mybatis.core.util.SqlDialectUtils@month('return_time')}
